// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, SCALAR_VAL, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide. */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    // In C, A is declared as A[nr][nq][np] and accessed as A[i][j][k].
    // The last index (k) is the fastest varying, so in Halide we map to
    // A(k, j, i) with shape (np, nq, nr).
    //
    // In C, C4 is declared as C4[np][np] and accessed as C4[i][j].
    // The last index (j) is the fastest varying, so in Halide we map to
    // C4(j, i) with shape (np, np).

    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = (DATA_TYPE) ((i*j + k) % np) / np;
    // Map: A_halide(k, j, i) = ...
    init_A(k, j, i) =
        cast<num_t>(((i * j + k) % np)) / np;

    // C4[i][j] = (DATA_TYPE) (i*j % np) / np;
    // We choose C4_halide(j, i) = C4[i][j].
    init_C4(j, i) =
        cast<num_t>(((i * j) % np)) / np;

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers: follow the C row-major layout mapping rules.
    //
    // C: A[nr][nq][np]  -> Halide: A(np, nq, nr), accessed as A(p, q, r)
    //     index mapping: A[r][q][p] == A(p, q, r)
    //
    // C: C4[np][np]     -> Halide: C4(np, np), accessed as C4(p, s)
    //     we will store C4[s][p] at C4(p, s) for the kernel.
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data.
    init_array(nr, nq, np, A, C4);

    // ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Halide implementation of kernel_doitgen.
    //
    // Original C:
    // for (r = 0; r < nr; r++)
    //   for (q = 0; q < nq; q++)  {
    //     for (p = 0; p < np; p++)  {
    //       sum[p] = 0.0;
    //       for (s = 0; s < np; s++)
    //         sum[p] += A[r][q][s] * C4[s][p];
    //     }
    //     for (p = 0; p < np; p++)
    //       A[r][q][p] = sum[p];
    //   }
    //
    // This is equivalent to:
    // A_new[r][q][p] = sum_s A[r][q][s] * C4[s][p]
    //
    // With our Buffer mapping:
    //   A_param(s, q, r) corresponds to A[r][q][s]
    //   C4_param(p, s)   corresponds to C4[s][p]
    //
    // So in Halide:
    //   doit(p, q, r) = sum_s A_param(s, q, r) * C4_param(p, s)

    Var p("p"), q("q"), r("r");
    RDom s(0, np, "s");

    Func doit("doit");

    // Pure definition: initialize the reduction.
    doit(p, q, r) = cast<num_t>(0);

    // Reduction update over s.
    doit(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // Schedule to mirror the original loop ordering:
    // Halide will by default nest loops as: for r, for q, for p, for s,
    // when realizing a 3D Func defined as doit(p, q, r) over {np, nq, nr}.
    // This matches the original C nesting r -> q -> p -> s, so we can use
    // the default schedule. If desired, we can make this explicit:
    doit.reorder(p, q, r);
    doit.update().reorder(p, s, q, r);

    // Prepare output buffer. We keep input and output separate to avoid
    // any aliasing issues (Halide assumes ImageParams and output Buffers
    // are independent).
    Halide::Buffer<num_t, 3> A_result(np, nq, nr);

    // Compile the kernel to machine code.
    doit.compile_jit();

    // Time the kernel execution.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    doit.realize(A_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (like print_array in the C version).
    // We mirror:
    // for (i = 0; i < nr; i++)
    //   for (j = 0; j < nq; j++)
    //     for (k = 0; k < np; k++)
    //       print A[i][j][k];
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < nr; i++) {
            for (int j = 0; j < nq; j++) {
                for (int k = 0; k < np; k++) {
                    // Mapping: A[i][j][k] == A_result(k, j, i)
                    if ((i * nq * np + j * np + k) % 20 == 0) {
                        std::cerr << '\n';
                    }
                    std::cerr << A_result(k, j, i);
                }
            }
        }
        std::cerr << '\n';
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
