// include common definitions (problem sizes, DATA_TYPE, SCALAR_VAL, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the input arrays A and C4.
 *
 * Original C signatures:
 *   void init_array(int nr, int nq, int np,
 *                   DATA_TYPE A[nr][nq][np],
 *                   DATA_TYPE C4[np][np]);
 *
 * Mapping to Halide:
 *   A: Buffer<num_t, 3> with shape (np, nq, nr) so that:
 *      A_C[r][q][p]  <->  A_H(p, q, r)
 *
 *   C4: Buffer<num_t, 2> with shape (np, np) so that:
 *      C4_C[i][j]    <->  C4_H(j, i)
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = (DATA_TYPE) ((i*j + k) % np) / np;
    // A_C[r][q][p] -> A_H(p, q, r) => indices (k, j, i)
    init_A(k, j, i) =
        cast<num_t>((i * j + k) % np) / cast<int>(np);

    // C4[i][j] = (DATA_TYPE) (i*j % np) / np;
    // C4_C[i][j] -> C4_H(j, i) => indices (j, i)
    init_C4(j, i) =
        cast<num_t>((i * j) % np) / cast<int>(np);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem sizes.
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers:
    // A: 3D, mapped as A(p, q, r) corresponding to C's A[r][q][p]
    Halide::Buffer<num_t, 3> A(np, nq, nr);

    // C4: 2D, mapped as C4(p, s) corresponding to C's C4[s][p]
    Halide::Buffer<num_t, 2> C4(np, np);

    // Output buffer for updated A:
    // This must be distinct from A to avoid in-place aliasing issues
    // with the reduction.
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);

    // Initialize data.
    init_array(nr, nq, np, A, C4);

    // Image parameters corresponding to A and C4.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars: p corresponds to the "k" index in C (innermost dimension of A),
    //       q corresponds to "j" (middle),
    //       r corresponds to "i" (outermost).
    Var p("p"), q("q"), r("r");

    // Reduction domain over s (the inner dimension of A and first index of C4).
    RDom s(0, A.dim(0).extent(), "s");  // 0 .. np-1

    // Halide version of kernel_doitgen.
    //
    // Original C kernel:
    //
    // for (r = 0; r < NR; r++)
    //   for (q = 0; q < NQ; q++) {
    //     for (p = 0; p < NP; p++) {
    //       sum[p] = 0;
    //       for (s = 0; s < NP; s++)
    //         sum[p] += A[r][q][s] * C4[s][p];
    //     }
    //     for (p = 0; p < NP; p++)
    //       A[r][q][p] = sum[p];
    //   }
    //
    // This is equivalent to:
    //   A_new[r][q][p] = sum_s A[r][q][s] * C4[s][p]
    //
    // with A_new written back to A at the end.
    Func doitgen("doitgen");

    // Pure definition: initialize sum to zero.
    doitgen(p, q, r) = cast<num_t>(0);

    // Update definition: accumulate over s.
    // Mapping:
    //   A[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]   -> C4_param(p, s)
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // Optionally, we can state the loop order explicitly to reflect
    // the original C loops: r (i), q (j), p (k), then s.
    //
    // By default, for doitgen(p, q, r), Halide generates:
    //   for r:
    //     for q:
    //       for p:
    //         for s:
    // which already matches the original structure, so no further
    // scheduling is strictly necessary. We keep the schedule simple.

    // JIT-compile the pipeline.
    doitgen.compile_jit();

    // Measure execution time of the kernel (realize).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute A_out = doitgen(A, C4).
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting array to stderr, similar to print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < nr; i++) {
            for (int j = 0; j < nq; j++) {
                for (int k = 0; k < np; k++) {
                    if ((i * nq * np + j * np + k) % 20 == 0) {
                        std::cerr << '\n';
                    }
                    // A[i][j][k] in C -> A_out(k, j, i) in Halide.
                    std::cerr << A_out(k, j, i);
                }
            }
        }
        std::cerr << '\n';
    }

    // Print timing (in seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
