#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C4.
 *
 * Original C code:
 *
 *   for (i = 0; i < nr; i++)
 *     for (j = 0; j < nq; j++)
 *       for (k = 0; k < np; k++)
 *         A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
 *   for (i = 0; i < np; i++)
 *     for (j = 0; j < np; j++)
 *       C4[i][j] = (DATA_TYPE) (i*j % np) / np;
 *
 * Mapping to Halide Buffers:
 *   C: A[i][j][k]  -> Buffer A(p, q, r) with p=k, q=j, r=i
 *   C: C4[i][j]    -> Buffer C4(p, s) with p=j, s=i  (so C4[p, s] == C4[s][p])
 */
static
void init_array(int nr, int nq, int np,
                Halide::Buffer<num_t, 3> A,
                Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var j("j"), i("i");

    Func init_A("init_A"), init_C4("init_C4");

    // A[r][q][p] = (r*q + p) % np / np
    // Buffer layout: A(p, q, r) = A[r][q][p]
    init_A(p, q, r) = cast<num_t>(((r * q + p) % np)) / cast<int>(np);

    // C4[s][p] = (s*p % np) / np
    // Buffer layout: C4(p, s) = C4[s][p]
    init_C4(j, i) = cast<num_t>(((i * j) % np)) / cast<int>(np);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers:
    // A_in:  input A, layout (p, q, r) = A[r][q][p]
    // A_out: output A after kernel, same layout
    // C4:    layout (p, s) = C4[s][p]
    Halide::Buffer<num_t, 3> A_in(np, nq, nr);
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A_in, C4);

    // ImageParams corresponding to A and C4
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A_in);
    C4_param.set(C4);

    // Halide implementation of kernel_doitgen
    //
    // Original C kernel:
    //
    // for (r = 0; r < NR; r++)
    //   for (q = 0; q < NQ; q++)  {
    //     for (p = 0; p < NP; p++)  {
    //       sum[p] = 0.0;
    //       for (s = 0; s < NP; s++)
    //         sum[p] += A[r][q][s] * C4[s][p];
    //     }
    //     for (p = 0; p < NP; p++)
    //       A[r][q][p] = sum[p];
    //   }
    //
    // This computes, for each (r,q), a matrix-vector multiply:
    //   A[r,q,:] <- A[r,q,:] * C4
    //
    // We express this as a 3D reduction over s:
    //   doitgen(p,q,r) = sum_s A[r,q,s] * C4[s,p]
    Var p("p"), q("q"), r("r");
    RDom s(0, A_in.dim(0).extent(), "s");  // s in [0, np)

    Func doitgen("doitgen");

    // Pure definition: initialize the reduction result
    doitgen(p, q, r) = cast<num_t>(0);

    // Update definition: accumulate over s
    // A_param(s, q, r) == A[r][q][s]
    // C4_param(p, s)   == C4[s][p]
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // A simple schedule that respects the logical loop structure:
    // outer loops over r, q, then inner over p, with reduction over s.
    doitgen.reorder(p, q, r);
    doitgen.update().reorder(p, s, q, r);

    // JIT-compile the kernel
    doitgen.compile_jit();

    // Measure execution time
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into A_out
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the results (similar to print_array in the C version)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r = 0; r < nr; r++) {
            for (int q = 0; q < nq; q++) {
                for (int p = 0; p < np; p++) {
                    std::cerr << A_out(p, q, r) << '\n';
                }
            }
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
