#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (PolyBench problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize A[nr][nq][np] and C4[np][np] in the same way as the C version.
// C layout:
//   A[i][j][k]  -> Buffer A(k, j, i)  -> A has shape (np, nq, nr)
//   C4[i][j]    -> Buffer C4(j, i)    -> here we'll store C4 as C4(p, s) = C4[s][p]
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r"), s("s");
    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = ( (i*j + k) % np ) / np
    // Map i -> r (dim 2), j -> q (dim 1), k -> p (dim 0)
    init_A(p, q, r) = cast<num_t>(((r * q + p) % np)) / Expr(np);

    // C4[i][j] = ( (i*j) % np ) / np
    // We'll store C4 as C4_buf(p, s) = C4[s][p]
    // So i -> s (dim 1), j -> p (dim 0)
    init_C4(p, s) = cast<num_t>(((s * p) % np)) / Expr(np);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from PolyBench headers)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers:
    // A_in  : input A (nr x nq x np), stored as (np, nq, nr)
    // A_out : output A (same shape)
    // C4    : np x np, stored as (p, s) = original C4[s][p]
    Halide::Buffer<num_t, 3> A_in(np, nq, nr);
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A_in, C4);

    // Halide parameters wrapping the input data
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A_in);
    C4_param.set(C4);

    // Vars and reduction domain
    Var p("p"), q("q"), r("r");
    RDom s(0, np, "s");

    // Main computational kernel in Halide form:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_s A[r][q][s] * C4[s][p]
    // In our buffer layout:
    //   r -> dim2, q -> dim1, s -> dim0 of A_param
    //   p -> dim0, s -> dim1 of C4_param (C4(p, s) = C4[s][p])
    Func doitgen("doitgen");
    doitgen(p, q, r) = Expr((num_t)0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // Schedule: mimic C loop nesting order as much as is reasonable.
    // C loops: for r, for q, for p, for s
    // Pure definition over (p, q, r): p varies fastest.
    doitgen.reorder(p, q, r);
    // Update step: make p outer over the reduction variable s,
    // then q, then r (roughly: r, q, p, s in C).
    doitgen.update().reorder(p, s, q, r);

    // JIT-compile the kernel
    doitgen.compile_jit();

    // Measure execution time
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: produce A_out from A_in and C4
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to stderr, to mirror the C version's print_array.
    // (This is mainly to prevent dead-code elimination and to allow correctness checks.)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int rr = 0; rr < nr; rr++) {
            for (int qq = 0; qq < nq; qq++) {
                for (int pp = 0; pp < np; pp++) {
                    std::cerr << A_out(pp, qq, rr) << '\n';
                }
            }
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
